  const n=src.length,act=aS/n,inh=iS/n,cross=cS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.07+sy*0.06-t*0.9)*0.5+Math.sin(sx*0.09-sy*0.08+t*1.5)*0.3)/2.8+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
