  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.2-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+sy*0.25+t*3)*Math.sin(sx*0.25-sy*0.3-t*2.5)*0.15;
  const blend=reaction*0.65+cell*0.25+micro*0.1,v=blend*0.5+0.5;
